/* Starts the cutscene, then during mode 3 (frames 900-10000) emits two particle beams from the listed moby. */
void update_kerwan_cutscene_effects(struct Moby *owner_moby) __asm__("FUN_L03_002e01d0");

void update_kerwan_cutscene_effects(struct Moby *owner_moby) {
    enum {
        CUTSCENE_EFFECTS_INITIALIZE = 0,
        CUTSCENE_EFFECTS_UPDATE = 1
    };
    char *moby;
    float from[4];
    float to[4];
    Vec4  zero;

    switch (owner_moby->state) {
    case CUTSCENE_EFFECTS_INITIALIZE:
        owner_moby->update_dist = 0xFF;
        owner_moby->state = 1;
        break;
    case CUTSCENE_EFFECTS_UPDATE:
        if (D_L03_0015F5C4 != 2)
            break;
        if (D_L03_0016C960.mode == 4 || D_L03_0016C960.mode == 10) {
            int cutscene_mode = D_L03_0016C960.mode;
            int i;
            i = 0;
            if (cutscene_mode == 4)
                i = 2;
            else if (cutscene_mode == 10)
                i = 0;
            cutscene_set_camera_target(D_L03_0016C960.mobys[i]);
        }
        if (D_L03_0015F5C4 != 2 || D_L03_0016C960.mode != 3)
            break;
        if (D_L03_0016C960.t < scale_game_frames(900))
            break;
        if (D_L03_0016C960.t > scale_game_frames(10000))
            break;
        moby = D_L03_0016C960.mobys[3];
        if (moby == 0)
            break;
        zero.q = 0;
        moby_point_position(moby, 0, from);
        moby_point_position(moby, 1, to);
        spawn_effect_particle_with_target_scalar(from,
                                                 &zero,
                                                 0x7F7F7F7F,
                                                 0x7F7F7F,
                                                 random_float_between(0.25f, 0.5f) * 210000.0f,
                                                 scale_game_frames(random_int_between(45, 60)));
        spawn_effect_particle_with_target_scalar(to,
                                                 &zero,
                                                 0x407F7F7F,
                                                 0x7F7F7F,
                                                 random_float_between(0.25f, 0.5f) * 210000.0f,
                                                 scale_game_frames(random_int_between(45, 60)));
        break;
    }
}

#include "qcopy.h"

/* places the camera behind the hero and rebuilds its orientation axes */
void rebuild_hero_relative_camera_transform(char *camera) __asm__("FUN_L03_002eb7e0");

void rebuild_hero_relative_camera_transform(char *camera) {
    char  *camera_data = *(char **)(camera + 0x70);
    float *camera_target_data = (float *)(camera_data + 0xB0);
    float *camera_offset_direction = (float *)(camera_data + 0xF0);
    float *camera_look_direction = (float *)(camera_data + 0x100);
    float  back[4];
    float  side[4];
    float  pos[4];
    float  look[4];
    float  camera_look_displacement[4];

    fast_vec_normalize(side, &hero.gravity_dir, -*(float *)(camera_data + 0xE0));
    fast_vec_normalize(back, camera_offset_direction, -*(float *)(camera_data + 0xD0));
    fast_vec_add(pos, &hero.motion.pos, side);
    fast_vec_add(camera + 0x30, pos, back);
    fast_vec_normalize(look, &hero.gravity_dir, -camera_target_data[5]);
    fast_vec_add(look, &hero.motion.pos, look);
    fast_vec_sub(camera_look_displacement, look, camera + 0x30);
    fast_vec_normalize(camera_look_direction, camera_look_displacement, 1.0f);
    fast_vec_normalize(camera, camera_look_direction, 1.0f);
    fast_vec_normalize(camera + 0x40, camera, 1.0f);
    qcopy(camera, camera + 0x40);
    fast_vec_cross(camera + 0x10, camera, &hero.gravity_dir);
    fast_vec_normalize(camera + 0x10, camera + 0x10, -1.0f);
    fast_vec_cross(camera + 0x20, camera + 0x10, camera);
}

